import os,sys
def getfile(path,R):
    rel=os.path.relpath(path,'/app/config')
    for r in range(R+1,420):
        p=f'/app/config-history/r{r:04d}/prev/{rel}'
        if os.path.exists(p): return open(p).read()
    return open(path).read()
def resolve(svc,env,host,R):
    kv={}
    def read(path,top_service):
        sec=None
        for l in getfile(path,R).splitlines() if path.startswith('/app/config/') else open(path).read().splitlines():
            l=l.strip()
            if not l or l.startswith('#'):continue
            if l.startswith('['):
                sec=l[1:-1];continue
            k,_,v=[x.strip() for x in l.partition('=')]
            if k=='include':
                if sec is None and not top_service:
                    pass
                if sec is not None: continue
                inc=v.replace('${env}',env).replace('${host}',host)
                read(os.path.normpath(os.path.join(os.path.dirname(path),inc)),False)
                continue
            if top_service or sec is None or sec==svc: kv[k]=v
    read(f'/app/services/{svc}/service.conf',True)
    return kv
if __name__=='__main__':
    for s in sys.argv[4:]:
        kv=resolve(s,sys.argv[1],sys.argv[2],int(sys.argv[3]))
        print(s,kv.get('port_base'),kv.get('port_offset'),kv.get('admin_port'),kv.get('enabled'))
